    .split("\n")
    .filter((item) => item.trim() && !item.startsWith("#"))
    .map((line) => {
      if (line.match(/^[*-]/)) {
        return line.replace(/^[*-]+\s*/, "- [ ] ").trim();
      }
      return `- [ ] ${line.trim()}`;
    })
    .join("\n");

  // Clean and format summary
  const cleanSummary = meetingSummary
    .split("\n")
    .filter((line) => line.trim() && !line.startsWith("#"))
    .map((line) => {
